#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, w, d;
    cin >> n >> w >> d;

    int64 g = std::gcd(w, d);
    i128 lcm = static_cast<i128>(w / g) * d;
    int64 favorablePerCycle = min(w, d);

    i128 cycles = static_cast<i128>(n) / lcm;
    i128 remainder = static_cast<i128>(n) % lcm;

    i128 answer128 = cycles * favorablePerCycle;
    answer128 += min(remainder, static_cast<i128>(favorablePerCycle - 1));

    int64 answer = static_cast<int64>(answer128);
    int64 common = std::gcd(answer, n);

    cout << answer / common << '/' << n / common << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 gcd128(i128 a, i128 b) {
    while (b != 0) {
        i128 r = a % b;
        a = b;
        b = r;
    }
    return a;
}

void print128(i128 x) {
    if (x == 0) {
        cout << '0';
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, w, d;
    cin >> n >> w >> d;

    int64 g = std::gcd(w, d);
    i128 lcm = i128(w / g) * d;
    i128 limit = min(w, d);

    i128 N = n;
    i128 favorable = (N / lcm) * limit
                   + min(N % lcm, limit - 1);

    i128 common = gcd128(favorable, N);

    print128(favorable / common);
    cout << '/';
    print128(N / common);
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, w, d;
    cin >> n >> w >> d;

    int64 g = std::gcd(w, d);
    i128 lcm = static_cast<i128>(w / g) * d;
    int64 m = min(w, d);

    i128 ans;
    if (lcm > n) {
        ans = min<i128>(n, static_cast<i128>(m) - 1);
    } else {
        ans = (static_cast<i128>(n) / lcm) * m +
              min<i128>(static_cast<i128>(m) - 1,
                        static_cast<i128>(n) % lcm);
    }

    int64 numerator = static_cast<int64>(ans);
    int64 divisor = std::gcd(numerator, n);

    cout << numerator / divisor << '/' << n / divisor << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, w, d;
    cin >> n >> w >> d;

    ll g = std::gcd(w, d);
    ll multiplier = d / g;
    ll limit = min(w, d);
    ll ans;

    if (multiplier > n / w) {
        ans = min(n, limit - 1);
    } else {
        ll lcm = w * multiplier;
        ans = (n / lcm) * limit + min(limit, n % lcm + 1) - 1;
    }

    ll common = std::gcd(ans, n);
    cout << ans / common << '/' << n / common << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, w, d;
    cin >> n >> w >> d;

    int64 g = std::gcd(w, d);
    i128 lcm = static_cast<i128>(w / g) * d;
    i128 minimum = min(w, d);

    i128 completeBlocks = static_cast<i128>(n) / lcm;
    i128 remainder = static_cast<i128>(n) % lcm;
    i128 answer = completeBlocks * minimum
                + min(minimum - 1, remainder);

    int64 numerator = static_cast<int64>(answer);
    int64 common = std::gcd(numerator, n);

    cout << numerator / common << '/' << n / common << '\n';
    return 0;
}

